{"code":"// --- Module 1 (the solution under test) ---
function assertIsDefined<T>(value: T, message?: string): asserts value is (T extends null | undefined ? never : T) {
  if (value === null || value === undefined) {
    throw new TypeError(message);
  }
}

// --- "Module 2": imported-and-called consumer, testing narrowing as a bare statement ---
function testNarrowingStringNullable(x: string | null): string {
  assertIsDefined(x);
  // After the bare call, `x` must be narrowed from `string | null` to `string`.
  const asString: string = x;
  return asString;
}

function testNarrowingStringUndefined(x: string | undefined): string {
  assertIsDefined(x);
  const asString: string = x;
  return asString;
}

function testNarrowingAllNullable(x: string | number | boolean | null | undefined): number {
  assertIsDefined(x, "must not be null/undefined");
  // After the bare call, `x` is narrowed to `string | number | boolean`.
  const asNonNullable: string | number | boolean = x;
  return asNonNullable as number;
}

function testFalsy(x: number): number {
  // 0, '', false, NaN are defined -> no throw, and no unexpected narrowing.
  assertIsDefined(x, "msg");
  return x;
}

function testThrowsNullable(x: string | null): never {
  assertIsDefined(x);
  const asString: string = x;
  return asString;
}

function testThrowsWithMessage(x: string | undefined): never {
  assertIsDefined(x, "my custom message");
  return 0 as string;
}"}

